import{_ as t,o as a,c as n,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const m=JSON.parse('{"title":"Tutorial Demos","description":"","frontmatter":{},"headers":[],"relativePath":"demos/TUTORIAL.md","filePath":"demos/TUTORIAL.md"}'),l={name:"demos/TUTORIAL.md"};function o(s,e,i,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="tutorial-demos" tabindex="-1">Tutorial Demos <a class="header-anchor" href="#tutorial-demos" aria-label="Permalink to &quot;Tutorial Demos&quot;">​</a></h1><p>The demos in <code>examples/learning/</code>, in the order to learn them, each teaching one feature a scene at a time. Each is described again on its genre&#39;s page; <a href="./../DEMOS">About Demos</a> lists every page of demos.</p><ul><li><a href="#hello_world">Hello World</a>: <code>01_hello_world.yml</code></li><li><a href="#pachelbel">Patterns Only</a>: <code>02_pachelbel.yml</code></li><li><a href="#mary_keychange">Key Changes</a>: <code>03_mary_keychange.yml</code></li><li><a href="#scale">Scales</a>: <code>04_scale.yml</code></li><li><a href="#voice_leading">Voice Leading</a>: <code>05_voice_leading.yml</code></li><li><a href="#chord_progression_generator">Progressions</a>: <code>06_chord_progression_generator.yml</code></li><li><a href="#blues_chords">Twelve-Bar Blues</a>: <code>07_blues_chords.yml</code></li><li><a href="#tie">Ties</a>: <code>08_tie.yml</code></li><li><a href="#groove">Grooves</a>: <code>09_groove.yml</code></li><li><a href="#mtn_king_direction">Directions</a>: <code>10_mtn_king_direction.yml</code></li><li><a href="#ode_to_joy_ratchet">Ratchets</a>: <code>11_ode_to_joy_ratchet.yml</code></li><li><a href="#sailor_arpeggiator">Arpeggiator</a>: <code>12_sailor_arpeggiator.yml</code></li><li><a href="#classic_strum">Strum</a>: <code>13_classic_strum.yml</code></li><li><a href="#acid_glide">Glide and Shorten</a>: <code>14_acid_glide.yml</code></li><li><a href="#acid_articulate">Articulate</a>: <code>15_acid_articulate.yml</code></li><li><a href="#bolero_swell">Swell</a>: <code>16_bolero_swell.yml</code></li><li><a href="#complex_gifts_chain">Chains</a>: <code>17_complex_gifts_chain.yml</code></li><li><a href="#techno_morph">Morphing</a>: <code>18_techno_morph.yml</code></li><li><a href="#hocket_shanty">Hocketing</a>: <code>19_hocket_shanty.yml</code></li><li><a href="#arrangement_shanty">Few Patterns</a>: <code>20_arrangement_shanty.yml</code></li><li><a href="#look_ma_no_notes">Grabbed Parts</a>: <code>21_look_ma_no_notes.yml</code></li><li><a href="#registers">Registers</a>: <code>22_registers.yml</code></li></ul><p><a id="hello_world"></a></p><h2 id="hello-world-01-hello-world-yml" tabindex="-1">Hello World: <code>01_hello_world.yml</code> <a class="header-anchor" href="#hello-world-01-hello-world-yml" aria-label="Permalink to &quot;Hello World: `01_hello_world.yml`&quot;">​</a></h2><p>The smallest set there is: a C major scale up in the first scene, down in the second, and up again in the third while a second track holds a C chord for a quarter note, every note a sixteenth. Three seconds long. Open it to see what a pattern, a track and a scene are, play it first when setting up real-time MIDI (<code>docs/MIDI_SETUP.md</code>), and record it first (<code>docs/RECORDING.md</code>).</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/01_hello_world.yml" target="_blank" rel="noreferrer"><code>examples/learning/01_hello_world.yml</code></a> · C major · 120 BPM · 0:03 · 3 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="pachelbel"></a></p><h2 id="patterns-only-02-pachelbel-yml" tabindex="-1">Patterns Only: <code>02_pachelbel.yml</code> <a class="header-anchor" href="#patterns-only-02-pachelbel-yml" aria-label="Permalink to &quot;Patterns Only: `02_pachelbel.yml`&quot;">​</a></h2><p>The opening of Pachelbel&#39;s Canon in D for three violins and a cello, using nothing but patterns and scenes, the way you might copy a score in. Because it&#39;s a canon, the violins share the same patterns, each a scene behind the one before.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/02_pachelbel.yml" target="_blank" rel="noreferrer"><code>examples/learning/02_pachelbel.yml</code></a> · D major · 44 BPM · 1:19 · 7 scenes · 4 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">tempo changes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="mary_keychange"></a></p><h2 id="key-changes-03-mary-keychange-yml" tabindex="-1">Key Changes: <code>03_mary_keychange.yml</code> <a class="header-anchor" href="#key-changes-03-mary-keychange-yml" aria-label="Permalink to &quot;Key Changes: `03_mary_keychange.yml`&quot;">​</a></h2><p>Mary Had a Little Lamb in four keys, one a scene: C major, C minor, E major, and whole tone on F#. The tune and its bass are one pattern each, written in scale degrees, and only each scene&#39;s Scale changes, so it shows how a key change is one field on the Scene page and no pattern moves.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/03_mary_keychange.yml" target="_blank" rel="noreferrer"><code>examples/learning/03_mary_keychange.yml</code></a> · C major · 112 BPM · 1:09 · 4 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">key changes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="scale"></a></p><h2 id="scales-04-scale-yml" tabindex="-1">Scales: <code>04_scale.yml</code> <a class="header-anchor" href="#scales-04-scale-yml" aria-label="Permalink to &quot;Scales: `04_scale.yml`&quot;">​</a></h2><p>Every scale llamatron knows, each run up an octave and back down from D, one scene per scale, in the order of the scale picker. Use it to preview a scale before choosing one. The demo shows that a scene can set its own scale, and that a degree past the top of a scale wraps up an octave.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/04_scale.yml" target="_blank" rel="noreferrer"><code>examples/learning/04_scale.yml</code></a> · D major · 120 BPM · 3:01 · 47 scenes · 1 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">key changes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="voice_leading"></a></p><h2 id="voice-leading-05-voice-leading-yml" tabindex="-1">Voice Leading: <code>05_voice_leading.yml</code> <a class="header-anchor" href="#voice-leading-05-voice-leading-yml" aria-label="Permalink to &quot;Voice Leading: `05_voice_leading.yml`&quot;">​</a></h2><p>Block chords on the piano over a bass in D major, three progressions each played three ways, back to back: in root position, every chord jumping up from its root; inverted by hand with the chord editor&#39;s Inv. row; and through the Voice leading generator, which plays each chord in the inversion and octave nearest the chord before. The last scene keeps the root in the bass.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/05_voice_leading.yml" target="_blank" rel="noreferrer"><code>examples/learning/05_voice_leading.yml</code></a> · D major · 96 BPM · 3:00 · 9 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="chord_progression_generator"></a></p><h2 id="progressions-06-chord-progression-generator-yml" tabindex="-1">Progressions: <code>06_chord_progression_generator.yml</code> <a class="header-anchor" href="#progressions-06-chord-progression-generator-yml" aria-label="Permalink to &quot;Progressions: `06_chord_progression_generator.yml`&quot;">​</a></h2><p>A pop song in C major made from three patterns one bar long, an arpeggio, a bass figure and a chord pad, each written over chord I and played through a Progression, a different one in every scene: Pop, Fifties, Andalusian in A minor, Pachelbel&#39;s eight chords, Pop again with the pad&#39;s chords inverted so that they move less, and Pop with the pad through a Voice leading generator.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/06_chord_progression_generator.yml" target="_blank" rel="noreferrer"><code>examples/learning/06_chord_progression_generator.yml</code></a> · C major · 96 BPM · 3:00 · 6 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="blues_chords"></a></p><h2 id="twelve-bar-blues-07-blues-chords-yml" tabindex="-1">Twelve-Bar Blues: <code>07_blues_chords.yml</code> <a class="header-anchor" href="#twelve-bar-blues-07-blues-chords-yml" aria-label="Permalink to &quot;Twelve-Bar Blues: `07_blues_chords.yml`&quot;">​</a></h2><p>A shuffle blues in G, where the walking bass, the comping chords and the riff are each one bar long, played through the twelve-bar blues and the quick-change blues. The comp&#39;s chord is a dominant seventh, which stays one on every chord of the blues, and the riff&#39;s blue note moves with the chords.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/07_blues_chords.yml" target="_blank" rel="noreferrer"><code>examples/learning/07_blues_chords.yml</code></a> · G major · 96 BPM · 3:00 · 6 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">grooves</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="tie"></a></p><h2 id="ties-08-tie-yml" tabindex="-1">Ties: <code>08_tie.yml</code> <a class="header-anchor" href="#ties-08-tie-yml" aria-label="Permalink to &quot;Ties: `08_tie.yml`&quot;">​</a></h2><p>An original downtempo piece in D Mixolydian whose pad draws its chords with the Tie row rather than with gates, so a chord lasts as long as the ties that follow it, and whose ending holds a bass note with ties alone, longer than any gate could make it. The demo also brings in the tracks one at a time, morphs a tune into its answer, grabs an echo and slides a filter, so it&#39;s the closest thing here to a finished song.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/08_tie.yml" target="_blank" rel="noreferrer"><code>examples/learning/08_tie.yml</code></a> · D mixolydian · 84 BPM · 2:59 · 9 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th><th style="text-align:center;">grabs</th><th style="text-align:center;">morphs</th><th style="text-align:center;">directions</th><th style="text-align:center;">ties</th><th style="text-align:center;">probability</th><th style="text-align:center;">key changes</th><th style="text-align:center;">tempo changes</th><th style="text-align:center;">CCs</th><th style="text-align:center;">registers</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="groove"></a></p><h2 id="grooves-09-groove-yml" tabindex="-1">Grooves: <code>09_groove.yml</code> <a class="header-anchor" href="#grooves-09-groove-yml" aria-label="Permalink to &quot;Grooves: `09_groove.yml`&quot;">​</a></h2><p>A twelve-bar organ shuffle in G minor, llamatron&#39;s own tune in the spirit of a sixties organ trio: a Hammond lick, walking pedals, seventh chords bubbling through an arpeggiator, and drums. The song shuffles with the factory groove <code>8th swing 66</code>, the pedals and pads keep grooves of their own, the drums are <code>off</code> so the kick and snare stay on the grid, and the scenes play it straight, drag it behind the beat with a groove of the set&#39;s own, and shuffle it harder, so you can hear how the track&#39;s choice wins over the scene&#39;s, which wins over the song&#39;s.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/09_groove.yml" target="_blank" rel="noreferrer"><code>examples/learning/09_groove.yml</code></a> · G minor · 130 BPM · 1:51 · 5 scenes · 5 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th><th style="text-align:center;">grooves</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="mtn_king_direction"></a></p><h2 id="directions-10-mtn-king-direction-yml" tabindex="-1">Directions: <code>10_mtn_king_direction.yml</code> <a class="header-anchor" href="#directions-10-mtn-king-direction-yml" aria-label="Permalink to &quot;Directions: `10_mtn_king_direction.yml`&quot;">​</a></h2><p>The theme of In the Hall of the Mountain King played in each of the step directions, from forward and the two reverses to pendulum, random and brownian. The demo also shows that a clip&#39;s direction overrides its pattern&#39;s.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/10_mtn_king_direction.yml" target="_blank" rel="noreferrer"><code>examples/learning/10_mtn_king_direction.yml</code></a> · B minor · 138 BPM · 2:33 · 11 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">directions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="ode_to_joy_ratchet"></a></p><h2 id="ratchets-11-ode-to-joy-ratchet-yml" tabindex="-1">Ratchets: <code>11_ode_to_joy_ratchet.yml</code> <a class="header-anchor" href="#ratchets-11-ode-to-joy-ratchet-yml" aria-label="Permalink to &quot;Ratchets: `11_ode_to_joy_ratchet.yml`&quot;">​</a></h2><p>The first line of Ode to Joy, slowed down to long notes, and then chopped up. The scenes named Ratchet use a pattern&#39;s own Ratchet, Ratchet offset and Probability rows. The scenes named AutoRatchet leave the pattern alone and do the chopping in a chain instead.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/11_ode_to_joy_ratchet.yml" target="_blank" rel="noreferrer"><code>examples/learning/11_ode_to_joy_ratchet.yml</code></a> · D major · 144 BPM · 4:00 · 18 scenes · 1 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th><th style="text-align:center;">probability</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="sailor_arpeggiator"></a></p><h2 id="arpeggiator-12-sailor-arpeggiator-yml" tabindex="-1">Arpeggiator: <code>12_sailor_arpeggiator.yml</code> <a class="header-anchor" href="#arpeggiator-12-sailor-arpeggiator-yml" aria-label="Permalink to &quot;Arpeggiator: `12_sailor_arpeggiator.yml`&quot;">​</a></h2><p>The verse of What Shall We Do With the Drunken Sailor, with its chords played through a different arpeggiator in every scene: step lengths, orders, octave ranges and jumps, offsets, and then combinations of them. The tune plays alongside, plainly, so you can mute it and hear only the arpeggio.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/12_sailor_arpeggiator.yml" target="_blank" rel="noreferrer"><code>examples/learning/12_sailor_arpeggiator.yml</code></a> · D dorian · 112 BPM · 3:26 · 24 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">chains</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="classic_strum"></a></p><h2 id="strum-13-classic-strum-yml" tabindex="-1">Strum: <code>13_classic_strum.yml</code> <a class="header-anchor" href="#strum-13-classic-strum-yml" aria-label="Permalink to &quot;Strum: `13_classic_strum.yml`&quot;">​</a></h2><p>An acoustic folk song in G major whose guitar chords are strummed as a hand crosses the strings, down on the beats and up between them, compared scene by scene: struck all at once, strummed tight, normal, with the full acoustic setting of fade, loose timing and light upstrokes, and rolled like a harp.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/13_classic_strum.yml" target="_blank" rel="noreferrer"><code>examples/learning/13_classic_strum.yml</code></a> · G major · 92 BPM · 2:52 · 9 scenes · 2 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th><th style="text-align:center;">strum</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="acid_glide"></a></p><h2 id="glide-and-shorten-14-acid-glide-yml" tabindex="-1">Glide and Shorten: <code>14_acid_glide.yml</code> <a class="header-anchor" href="#glide-and-shorten-14-acid-glide-yml" aria-label="Permalink to &quot;Glide and Shorten: `14_acid_glide.yml`&quot;">​</a></h2><p>Fluid acid techno for a synth with portamento: one sixteen-note acid line from start to finish, and Glide and Shorten rows of 5, 7 and 3 steps putting its slides and short notes somewhere new each bar, though the line itself never changes.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/14_acid_glide.yml" target="_blank" rel="noreferrer"><code>examples/learning/14_acid_glide.yml</code></a> · A minor · 128 BPM · 3:00 · 8 scenes · 4 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chains</th><th style="text-align:center;">feel</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="acid_articulate"></a></p><h2 id="articulate-15-acid-articulate-yml" tabindex="-1">Articulate: <code>15_acid_articulate.yml</code> <a class="header-anchor" href="#articulate-15-acid-articulate-yml" aria-label="Permalink to &quot;Articulate: `15_acid_articulate.yml`&quot;">​</a></h2><p>An acid house line played the whole way through, whose notes lengthen from short blips into long, gliding, joined notes over each scene while its filter opens, with no gate changed. The demo sets Articulate on the scenes, on the line itself and as a generator that bounces between short and long every bar, and a register bound to CC 74 opens the filter as the notes lengthen.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/15_acid_articulate.yml" target="_blank" rel="noreferrer"><code>examples/learning/15_acid_articulate.yml</code></a> · A minor · 120 BPM · 3:00 · 9 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">CCs</th><th style="text-align:center;">registers</th><th style="text-align:center;">binding</th><th style="text-align:center;">shapes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="bolero_swell"></a></p><h2 id="swell-16-bolero-swell-yml" tabindex="-1">Swell: <code>16_bolero_swell.yml</code> <a class="header-anchor" href="#swell-16-bolero-swell-yml" aria-label="Permalink to &quot;Swell: `16_bolero_swell.yml`&quot;">​</a></h2><p>An original piece in three in the manner of Ravel&#39;s Bolero: one tune and one snare rhythm, nine scenes of one unbroken crescendo from soft to full force, climbing evenly in loudness, without one velocity changed in a pattern. Each scene&#39;s Swell starts where the one before ended, the first three scenes keep the same instruments so that only the loudness climbs, and in the last the timpani run through a Swell generator that accents every downbeat. Use velocity-sensitive instruments to hear it.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/16_bolero_swell.yml" target="_blank" rel="noreferrer"><code>examples/learning/16_bolero_swell.yml</code></a> · C major · 72 BPM · 3:00 · 9 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">shapes</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="complex_gifts_chain"></a></p><h2 id="chains-17-complex-gifts-chain-yml" tabindex="-1">Chains: <code>17_complex_gifts_chain.yml</code> <a class="header-anchor" href="#chains-17-complex-gifts-chain-yml" aria-label="Permalink to &quot;Chains: `17_complex_gifts_chain.yml`&quot;">​</a></h2><p>Simple Gifts on a single track, growing from the plain tune into triads, then synthwave, then happy metal, using only five patterns and a chain for each scene. The demo shows that a chain runs its steps in order, so an arpeggiator followed by an AutoRatchet sounds different from the other way round.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/17_complex_gifts_chain.yml" target="_blank" rel="noreferrer"><code>examples/learning/17_complex_gifts_chain.yml</code></a> · A major · 120 BPM · 2:40 · 10 scenes · 1 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="techno_morph"></a></p><h2 id="morphing-18-techno-morph-yml" tabindex="-1">Morphing: <code>18_techno_morph.yml</code> <a class="header-anchor" href="#morphing-18-techno-morph-yml" aria-label="Permalink to &quot;Morphing: `18_techno_morph.yml`&quot;">​</a></h2><p>A 16-step minimal techno groove whose bass and lead slowly turn into other patterns over 8 or 16 bars, in each morph style. The lead turns into the opening of Für Elise.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/18_techno_morph.yml" target="_blank" rel="noreferrer"><code>examples/learning/18_techno_morph.yml</code></a> · A minor · 126 BPM · 2:17 · 8 scenes · 4 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">morphs</th><th style="text-align:center;">CCs</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="hocket_shanty"></a></p><h2 id="hocketing-19-hocket-shanty-yml" tabindex="-1">Hocketing: <code>19_hocket_shanty.yml</code> <a class="header-anchor" href="#hocketing-19-hocket-shanty-yml" aria-label="Permalink to &quot;Hocketing: `19_hocket_shanty.yml`&quot;">​</a></h2><p>The Wellerman, held by a muted track called SILENT melody, with up to four voices taking turns at its notes, one note each, through a Hocket generator that names the melody&#39;s track as its source. That&#39;s called hocketing. One voice plays every note, two alternate, and four each play every fourth note; each voice has a sound of its own, flute, clarinet, oboe and violin, to hear the tune pass between them.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/19_hocket_shanty.yml" target="_blank" rel="noreferrer"><code>examples/learning/19_hocket_shanty.yml</code></a> · A minor · 100 BPM · 2:14 · 7 scenes · 5 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chains</th><th style="text-align:center;">hocket</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="arrangement_shanty"></a></p><h2 id="few-patterns-20-arrangement-shanty-yml" tabindex="-1">Few Patterns: <code>20_arrangement_shanty.yml</code> <a class="header-anchor" href="#few-patterns-20-arrangement-shanty-yml" aria-label="Permalink to &quot;Few Patterns: `20_arrangement_shanty.yml`&quot;">​</a></h2><p>The Wellerman again, with eight parts built from only four note patterns. The harmony is the melody patterns transposed on its track, the bass grabs the roots of the pad&#39;s chords, and a counter-line grabs the melody in its own rhythm. Read this one to see how to set up a song so that changing one pattern changes every part that follows it.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/20_arrangement_shanty.yml" target="_blank" rel="noreferrer"><code>examples/learning/20_arrangement_shanty.yml</code></a> · A minor · 100 BPM · 2:34 · 8 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">chains</th><th style="text-align:center;">grabs</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="look_ma_no_notes"></a></p><h2 id="grabbed-parts-21-look-ma-no-notes-yml" tabindex="-1">Grabbed Parts: <code>21_look_ma_no_notes.yml</code> <a class="header-anchor" href="#grabbed-parts-21-look-ma-no-notes-yml" aria-label="Permalink to &quot;Grabbed Parts: `21_look_ma_no_notes.yml`&quot;">​</a></h2><p>A gospel song in A flat where the bass, the piano and the lead hold no notes at all. The organ holds one seventh chord a bar, moved through the changes by Progression generators, and every other part is Grab steps that take the root of the organ&#39;s chord and build on it: the bass an octave down, the piano&#39;s chords from its Chord row, and the lead three ways, from the register rows, from an arpeggiator and from climbing and falling ratchets. The last chorus goes up a half step, and every part follows.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/21_look_ma_no_notes.yml" target="_blank" rel="noreferrer"><code>examples/learning/21_look_ma_no_notes.yml</code></a> · Ab major · 76 BPM · 2:57 · 6 scenes · 7 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">arps</th><th style="text-align:center;">ratchets</th><th style="text-align:center;">chains</th><th style="text-align:center;">grabs</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th><th style="text-align:center;">key changes</th><th style="text-align:center;">registers</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr></tbody></table><p><a id="registers"></a></p><h2 id="registers-22-registers-yml" tabindex="-1">Registers: <code>22_registers.yml</code> <a class="header-anchor" href="#registers-22-registers-yml" aria-label="Permalink to &quot;Registers: `22_registers.yml`&quot;">​</a></h2><p>An acid techno riff of five notes, changed bar by bar by the four registers, AX to DX. AX, BX and CX each move a different note of the riff, in cycles of 4, 6 and 5 bars, then all three at once. Then DX fades the riff, kick and hat out together over six repeats of the last scene.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/22_registers.yml" target="_blank" rel="noreferrer"><code>examples/learning/22_registers.yml</code></a> · A minor · 132 BPM · 1:35 · 5 scenes · 3 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">registers</th></tr></thead><tbody><tr><td style="text-align:center;">✓</td></tr></tbody></table>',113)])])}const y=t(l,[["render",o]]);export{m as __pageData,y as default};
